using System;using System.Globalization;using System.Text.RegularExpressions;
public static class EvidenceDates {
 public static string Display(object raw){if(raw==null||String.IsNullOrWhiteSpace(Convert.ToString(raw)))return "не сохранена / неизвестна";string s=Convert.ToString(raw,CultureInfo.InvariantCulture).Trim();long epoch;if(Int64.TryParse(s,NumberStyles.Integer,CultureInfo.InvariantCulture,out epoch)){if(epoch==0)return "нулевая метка0; дата не подтверждена";try{return new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero).AddSeconds(epoch).UtcDateTime.ToString("yyyy-MM-dd HH:mm:ss 'UTC'",CultureInfo.InvariantCulture)+" (Unix raw: "+s+")";}catch{return "невалидная Unix-метка (raw: "+s+")";}}DateTimeOffset dto;if(Regex.IsMatch(s,@"^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:\d{2})$")&&DateTimeOffset.TryParse(s,CultureInfo.InvariantCulture,DateTimeStyles.None,out dto))return dto.UtcDateTime.ToString("yyyy-MM-dd HH:mm:ss 'UTC'",CultureInfo.InvariantCulture)+" (raw: "+s+")";DateTime day;if(DateTime.TryParseExact(s,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out day))return s+" (время и часовой пояс не сохранены)";return "дата не подтверждена; raw: "+s;}
}
